    "ingestedAt": "16/11/2026 às 16:19",
    "imageUrl": "https://www.camara.leg.br/midias/image/2026/11/img20260714163113727-768x473.jpg",
    "imageCaption": "Laura Carneiro, relatora da proposta",
    "imageCredit": "Bruno Spada/Câmara dos Deputados",
    "imageAlt": "Deputada Laura Carneiro (PSD-RJ) fala em comissão da Câmara dos Deputados",
